builder.AddDistillClient("distill", options =>
    options.DefaultChannel = "checkout.latency");

var app = builder.Build();
var client = app.Services.GetRequiredService<DistillClient>();
await client.ReconcileChannelAsync(new CreateChannelRequest
{
    Name = "checkout.latency", Version = "1",
    SinkId = "primary", Preset = ChannelPreset.Metrics
});

app.Logger.LogInformation("Checkout took {value} ms", 184);
app.Run();

var database = builder.AddPostgres("pg").AddDatabase("distill-db");
var distill = builder.AddDistill("distill")
    .WithLocalBuild()
    .WithSink(database, name: "primary")
    .WithEnvironment("DISTILL_AUTO_MIGRATE", "true"); // local development

builder.AddProject<Projects.Checkout>("checkout")
    .WithReference(distill);
